validate:
(result, args, expected) => {
  const [n, prerequisites] = args;
  if (!Array.isArray(result)) return "Return an array of course numbers.";
  if (expected.length === 0) return result.length === 0 ? true : "The prerequisites contain a cycle, so no valid order exists: return [].";
  if (result.length === 0) return `An order exists (for example [${expected.join(", ")}]), so don't return [].`;
  if (result.length !== n) return `The order must list all ${n} courses exactly once, but it has ${result.length} entries.`;
  const pos = new Array(n).fill(-1);
  for (let i = 0; i < result.length; i++) {
    const c = result[i];
    if (!Number.isInteger(c) || c < 0 || c >= n) return `${JSON.stringify(c)} is not a course number from 0 to ${n - 1}.`;
    if (pos[c] !== -1) return `Course ${c} appears more than once.`;
    pos[c] = i;
  }
  for (const [course, pre] of prerequisites) {
    if (pos[pre] > pos[course]) return `Course ${pre} is a prerequisite of course ${course}, so it must come first, but your order puts it after.`;
  }
  return true;
}
